import { Pool } from 'pg'

export const priceFor = async (sku: string, pool: Pool): Promise<number> => {
  const result = await pool.query('select base_price, quantity from prices where sku = $1', [sku])
  const basePrice = result.rows[0].base_price
  const quantity = result.rows[0].quantity
  if (quantity >= 100) {
    return basePrice * 0.8
  }
  if (quantity >= 10) {
    return basePrice * 0.9
  }
  return basePrice
}

import axios from 'axios'

export const isEligible = async (userId: string) => {
  const response = await axios.get(`/scores/${userId}`)
  const creditScore = response.data.score
  const minimumScore = 650
  return creditScore >= minimumScore
}

import { readFileSync } from 'node:fs'

export const taxRateFor = (region: string): number => {
  const rates = JSON.parse(readFileSync('./tax-rates.json', 'utf8'))
  switch (region) {
    case 'CA':
      return rates.CA
    case 'NY':
      return rates.NY
    default:
      return rates.default
  }
}

import Stripe from 'stripe'

export const placeOrder = async (order: { items: { price: number; quantity: number }[] }, stripe: Stripe) => {
  const subtotal = order.items.reduce((sum, item) => sum + item.price * item.quantity, 0)
  const freeShippingThreshold = 100
  const shippingFee = subtotal >= freeShippingThreshold ? 0 : 12
  const total = subtotal + shippingFee
  return stripe.charges.create({ amount: total * 100, currency: 'usd' })
}

import { Pool } from 'pg'

export const findUser = async (id: string, pool: Pool): Promise<{ id: string; name: string; email: string } | null> => {
  const result = await pool.query('select id, name, email from users where id = $1', [id])
  const row = result.rows[0]
  if (!row) return null
  return { id: row.id, name: row.name, email: row.email }
}

import express from 'express'

export const deactivateUserHandler = async (
  req: express.Request,
  res: express.Response,
  service: { deactivate: (id: string) => Promise<boolean> }
) => {
  const deactivated = await service.deactivate(req.params.id)
  if (!deactivated) {
    return res.status(404).send()
  }
  return res.status(200).send()
}

